import re

part1 = """16,17, 19,20, 22,23, 25,26, 28,29 серпня 2026 року - майор ВИШНЕВИЙ Анатолій Михайлович начальник озброєння – заступник начальника логістики; 01,02, 04,05, 07,08, 10,11, 13,14 серпня 2026 року - майор ПОДЕНЕЖКО Андрій Вікторович заступник начальника озброєння логістики; 16,17, 19,20, 22,23, 25,26, 28,29 серпня 2026 року - полковник ПЕРЕДЕРІЙ Олег Миколайович начальник служби засобів ураження озброєння логістики; 01,02, 04,05, 07,08, 10,11, 13,14 серпня 2026 року - старший лейтенант ІВАНЮК Іван Іванович помічник начальника служби засобів ураження озброєння логістики; 02,03, 05,06, 08,09, 11,12, 14,15 серпня 2026 року - старший солдат СМИКІВ Володимир Богданович діловод служби засобів ураження озброєння логістики; 22,23, 25,26, 28 серпня 2026 року - майор ДЖУР Едуард Володимирович начальник служби засобів ближнього бою та розвідки озброєння логістики; 01,02, 04,05, 07,08, 10,11, 13,14 серпня 2026 року - лейтенант ЗЕРНОВ Ігор Олександрович помічник начальника служби засобів ближнього бою та розвідки озброєння логістики; 02,03, 05,06, 08,09, 11,12, 14,15 серпня 2026 року - старший сержант ГАРАСИМЧУК Володимир Ігорович діловод служби засобів ближнього бою та розвідки озброєння логістики; 15,16, 18,19, 21,22, 24 серпня 2026 року - капітан РУДЕНКО Олександр Іванович начальник служби наземних систем озброєння озброєння логістики; 01,02, 04,05, 07,08, 10 серпня 2026 року - капітан ГОНЧАРОВ Денис Олександрович помічник начальника служби наземних систем озброєння озброєння логістики; 04,05, 07,08, 10,11, 13,14, 16,17 серпня 2026 року - капітан НЕЧЕПУРЕНКО Олег Олександрович начальник служби військової техніки озброєння логістики; 19,20, 22,23, 25,26, 28 серпня 2026 року - капітан КЛИВНЯК Олексій Олександрович помічник начальника служби військової техніки озброєння логістики; 10,11, 13,14, 16,17, 19,20, 22,23 серпня 2026 року - старший солдат ДУДОК Юрій Васильович діловод служби військової техніки озброєння логістики; 01,02, 04,05, 07 серпня 2026 року - старший солдат ФРЕНЦЕР Богдан Юрійович діловод служби військової техніки озброєння логістики; 01,02, 04,05, 07,08, 10,11, 13,14 серпня 2026 року - молодший лейтенант КАБАЦЬКИЙ Олександр Сергійович помічник начальника служби авіації та протиповітряної оборони озброєння логістики; 16,17, 19,20, 22,23, 25,26, 28,29 серпня 2026 року - молодший лейтенант НІКІТІН Денис Сергійович помічник начальника служби озброєння, військової техніки та майна спеціальних військ озброєння логістики; 01,02, 04,05, 07 серпня 2026 року - старший солдат ЗЕЛЕНЮК Віталій Юрійович діловод служби озброєння, військової техніки та майна спеціальних військ озброєння логістики; 24,25, 27,28 серпня 2026 року - старший лейтенант ВАСИЛЬЧИКОВ Ілля Володимирович начальник служби авіації та протиповітряної оборони озброєння логістики; 01,02, 04,05, 07,08, 10,11, 13,14 серпня 2026 року - капітан МАЄР Андрій Давидович помічник начальника служби авіації та протиповітряної оборони озброєння логістики; 16,17, 19,20, 22,23, 25,26, 28,29 серпня 2026 року - старший лейтенант ШЕВЦОВ Олексій Сергійович помічник начальника служби авіації та протиповітряної оборони озброєння логістики; 02,03, 05,06, 08,09, 11,12, 14,15 серпня 2026 року - старший сержант СОРОКА Любомир Васильович діловод служби авіації та протиповітряної оборони озброєння логістики; 17,18, 20,21, 23,24, 26,27, 29,30 серпня 2026 року - молодший сержант ФІЛІПЧУК Богдан Петрович діловод служби авіації та протиповітряної оборони озброєння логістики; 03,04, 06,07, 09,10, 12,13, 15,16 серпня 2026 року - старший солдат АГАДЖАНОВ Чінгіз Тофікович діловод служби авіації та протиповітряної оборони озброєння логістики; 03,04, 06,07, 09,10, 12,13, 15,16 серпня 2026 року - майор ЯНИШИН Степан Володимирович начальник служби метрології та стандартизації озброєння логістики"""

part2 = """17,18, 20,21, 23,24, 26,27, 29,30 серпня 2026 року - капітан ЛИТВИНЕНКО Олена Сергіївна начальник тилу – заступник начальника логістики; 03,04, 06,07, 09,10, 12,13, 15,16 серпня 2026 року - підполковник ДЕКЕТ Микола Миколайович заступник начальника тилу логістики; 01,02, 04,05, 07,08, 10,11, 13,14 серпня 2026 року - старший лейтенант КОЛПАКОВ Віталій Вікторович начальник служби пально-мастильних матеріалів тилу логістики; 17,18, 20,21, 23,24, 26,27, 29,30 серпня 2026 року - старший лейтенант КРУТЬКО Микола Іванович помічник начальника служби пально-мастильних матеріалів тилу логістики; 18,19, 21,22, 24,25, 27,28, 30,31 серпня 2026 року - старший солдат РУДНИЦЬКИЙ Тарас Васильович діловод служби пально-мастильних матеріалів тилу логістики; 01,02, 04,05, 07,08, 10 серпня 2026 року - майор САВЧЕНКО Олександр Миколайович начальник продовольчої служби тилу логістики; 18,19,21,22,24,25,27,28,30,31 серпня 2026 року - молодший лейтенант ЦІЛЬМАК Олег Валерійович помічник начальника продовольчої служби тилу логістики; 03,04, 06,07, 09,10, 12,13, 15,16 серпня 2026 року - старший солдат ЛЕВИЦЬКИЙ Василь Іванович діловод продовольчої служби тилу логістики; 18,19, 21,22, 24,25, 27,28, 30,31 серпня 2026 року - старший солдат ПЕТРИШАК Назар Маркіянович діловод продовольчої служби тилу логістики; 03,04, 06,07, 09,10, 12,13, 15,16 серпня 2026 року - старший лейтенант ДМИТРИК Назар Іванович начальник речової служби тилу логістики; 18,19, 21,22, 24,25, 27,28, 30,31 серпня 2026 року - лейтенант ЗАГАЙКО Андрій Зіновійович помічник начальника речової служби тилу логістики; 08,09, 11,12, 14,15, 17,18, 20,21 серпня 2026 року - старший солдат ГОЯНЮК Тарас Володимирович діловод речової служби тилу логістики; 16,17, 19,20, 22,23, 25 серпня 2026 року - старший солдат СТАДНИК Дмитро Миколайович діловод речової служби тилу логістики; 03,04, 06,07, 09,10, 12,13, 15,16 серпня 2026 року - старший солдат КРАВЧУК Олександр Олегович діловод служби інженерно-інфраструктурного забезпечення тилу логістики"""

ranks = [
    "молодший лейтенант", "старший лейтенант", "лейтенант",
    "полковник", "підполковник", "майор", "капітан",
    "головний сержант", "старший сержант", "молодший сержант", "сержант",
    "старший прапорщик", "прапорщик",
    "старший солдат", "солдат"
]

all_text = part1 + "; " + part2
entries = [e.strip() for e in all_text.split(';') if e.strip()]
parsed = []

for idx, entry in enumerate(entries):
    m_dates = re.match(r'^([0-9,\s]+)\s+серпня\s+2026\s+року\s*-\s*(.*)$', entry, re.IGNORECASE)
    if not m_dates:
        print("FAILED PARSE DATES:", entry)
        continue
    
    dates_str = m_dates.group(1)
    day_nums = [int(d.strip()) for d in dates_str.replace(' ', '').split(',') if d.strip()]
    rest = m_dates.group(2).strip()

    found_rank = ""
    rest_after_rank = rest
    for r in ranks:
        if rest.lower().startswith(r):
            found_rank = r
            rest_after_rank = rest[len(r):].strip()
            break
    
    parts = rest_after_rank.split(maxsplit=3)
    if len(parts) >= 3 and parts[0].isupper():
        pib = f"{parts[0]} {parts[1]} {parts[2]}"
        posada = parts[3] if len(parts) > 3 else ""
    else:
        pib = rest_after_rank
        posada = ""
        
    parsed.append({
        'row': idx + 3,
        'dates': day_nums,
        'rank': found_rank,
        'pib': pib,
        'posada': posada
    })

print(f"TOTAL PARSED PERSONNEL: {len(parsed)}")
for p in parsed:
    print(f"Row {p['row']:2d}: [B={p['rank']:18s}] [C={p['pib']:32s}] [A={p['posada']}]")
